"""Service entry point: JSON-lines in, one JSON reply per line, stateful."""
import json
import pathlib
import sys

HERE = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
sys.path.insert(0, '/workspace/vendor/networkx-3.4.2-py3-none-any.whl')

from service import handle          # noqa: E402
from wire import decode             # noqa: E402

INVALID = {'status': 'invalid'}


def main():
    out = sys.stdout
    for raw in sys.stdin.buffer:
        try:
            text = raw.decode('utf-8')
        except UnicodeDecodeError:
            reply = INVALID
        else:
            try:
                request = decode(text)
                reply = handle(request)
            except Exception:
                reply = INVALID
        try:
            out.write(json.dumps(reply, separators=(',', ':')))
            out.write('\n')
            out.flush()
        except Exception:
            break


if __name__ == '__main__':
    main()
PYEOF
